import {repairClasses,requestStatuses,findProfiles,ratingOf} from './market.js';
export function createMarketplace(c){
 const {esc,icon,money,total,heading,empty,openModal,toast}=c;const state=()=>c.state();let filters={};
 const names={catalog:'Найти исполнителя',profile:'Профиль исполнителя',requests:'Заявки и предложения',myprofile:'Мой профиль'};
 const select=(name,label,values)=>`<label class="field">${label}<select name="${name}"><option value="">Все</option>${values.map(v=>`<option ${filters[name]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
 const art=(palette='sage')=>`<div class="room-art ${palette}"><div class="room-window"></div><div class="room-sofa"></div><div class="room-plant"></div><div class="room-lamp"></div><span>Иллюстрация проекта</span></div>`;
 const cover=work=>work?.image?`<img class="portfolio-photo" src="${esc(work.image)}" alt="${esc(work.title)}">`:art(work?.palette);
 const stars=p=>{const r=ratingOf(p,state().reviews);return `<span class="rating">★ ${r.count?r.average.toFixed(1):'—'}</span> <small>${r.count} отзывов${r.verified?` · ${r.verified} по проектам`:''}</small>`;};
 const card=p=>`<article class="provider-card"><div class="provider-art">${cover(p.portfolio[0])}<span class="badge ${p.type==='Бригада'?'approved':'changes'}">${esc(p.type)}</span></div><div class="provider-body"><div class="provider-top"><span class="provider-monogram">${esc(p.name.slice(0,2).toUpperCase())}</span><div><h2>${esc(p.name)}</h2><small>${esc(p.city)} · ${p.experience} лет опыта</small></div></div><div class="provider-rating">${stars(p)}</div><p>${esc(p.specialty)}</p><div class="chips">${p.repairClasses.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="provider-price"><div><small>Ориентир для «${esc(p.specialty)}»</small><strong>от ${money(p.rate)} <small>/ м²</small></strong></div><button class="btn small" data-go="profile" data-id="${p.id}">Профиль ${icon('arrow',13)}</button></div></div></article>`;
 function catalog(){const s=state(),rows=findProfiles(s.profiles,s.reviews,filters);return `${heading('Найдите свою команду','Бригады и специалисты под ваш ремонт, площадь и бюджет.','','Сначала люди, затем ремонт')}<div class="market-intro"><div><h2>Ваш ремонт начинается<br>с правильного исполнителя.</h2><p>Сравните опыт, портфолио и расценки. Запросите смету, прежде чем создавать проект.</p><div class="market-steps"><span>01 Выберите</span><span>02 Согласуйте смету</span><span>03 Ведите проект</span></div></div>${art('sage')}</div><form id="market-filter-form" class="market-filters"><label class="field filter-search">Поиск<input name="q" value="${esc(filters.q||'')}" placeholder="Название или специализация"></label>${select('city','Город',[...new Set(s.profiles.map(p=>p.city))])}${select('type','Исполнитель',['Бригада','Специалист'])}${select('repairClass','Класс ремонта',repairClasses)}${select('specialty','Работы',[...new Set(s.profiles.map(p=>p.specialty))])}<label class="field">До, ₸ / м²<input name="maxRate" type="number" min="1" value="${esc(filters.maxRate||'')}" placeholder="Например, 30000"></label><label class="field">Площадь, м²<input name="area" type="number" min="1" value="${esc(filters.area||'')}" placeholder="Например, 78"></label><label class="field">Сортировка<select name="sort"><option value="experience">По опыту</option><option value="price" ${filters.sort==='price'?'selected':''}>Сначала дешевле</option><option value="rating" ${filters.sort==='rating'?'selected':''}>По рейтингу</option></select></label><div class="actions"><button class="btn primary" type="submit">${icon('search',15)} Найти</button><button class="btn" type="button" data-act="market-reset">Сбросить</button></div></form><div class="notice">Расценки ориентировочные, за м² выбранного вида работ. Сравнивайте исполнителей одной специализации: электромонтаж и ремонт под ключ имеют разный состав. Итоговую смету подрядчик готовит по вашей заявке.</div><div class="filter-bar"><strong>Найдено: ${rows.length}</strong><span class="muted">Демо-профили и отзывы помечены в карточке исполнителя</span></div><div class="provider-grid">${rows.map(card).join('')||empty('Подходящих исполнителей нет. Измените фильтры.')}</div>`;}
 function profile(pid){const p=state().profiles.find(p=>p.id===pid);if(!p)return empty('Профиль недоступен');const own=p.ownerId===state().user.id;return `${heading(esc(p.name),`${esc(p.city)} · ${esc(p.type)} · ${esc(p.specialty)}`,`<button class="btn" data-go="catalog">К каталогу</button>${own?'<button class="btn primary" data-act="profile-edit">Редактировать</button>':state().user.role==='client'?`<button class="btn primary" data-act="request-new" data-id="${p.id}">Выбрать и запросить смету ${icon('arrow',15)}</button>`:''}`)}${p.demo?'<div class="notice demo">Демонстрационный профиль. Портфолио показано иллюстрациями, исходные отзывы — тестовые примеры.</div>':''}<div class="project-detail"><div><section class="panel"><div class="panel-body"><div class="provider-top"><span class="provider-monogram large">${esc(p.name.slice(0,2).toUpperCase())}</span><div><h2>${esc(p.name)}</h2>${stars(p)}</div></div><p style="margin-top:20px">${esc(p.bio)}</p><div class="chips">${p.repairClasses.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><h2>Портфолио · ${p.portfolio.length}</h2>${own?'<button class="link-btn" data-act="portfolio-new">+ Добавить работу</button>':''}</div><div class="panel-body portfolio-grid">${p.portfolio.map(work=>`<article>${cover(work)}<h3>${esc(work.title)}</h3><p class="muted">${esc(work.description)}</p></article>`).join('')||empty('Исполнитель ещё не добавил работы.')}</div></section><section class="panel"><div class="panel-head"><h2>Отзывы и оценки</h2>${stars(p)}</div><div class="panel-body">${state().reviews.filter(r=>r.profileId===p.id).map(r=>`<article class="review"><div class="actions"><strong>${esc(r.author)}</strong><span class="rating">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span><span class="badge ${r.demo?'draft':'approved'}">${r.demo?'Демо-отзыв':'По завершённому проекту'}</span></div><p>${esc(r.text)}</p></article>`).join('')||empty('Отзывы появятся после завершённых проектов.')}</div></section></div><aside><section class="panel"><div class="panel-head"><h2>Об исполнителе</h2></div><div class="panel-body"><div class="stat-value">от ${money(p.rate)} <small style="font-size:12px">/ м²</small></div><p class="muted">Ориентир: ${esc(p.specialty)}. Финальная стоимость — в предложении.</p><div class="budget-row"><span>Опыт</span><strong>${p.experience} лет</strong></div><div class="budget-row"><span>Объём объекта</span><strong>${p.minArea}–${p.maxArea} м²</strong></div><div class="budget-row"><span>Город</span><strong>${esc(p.city)}</strong></div>${state().user.role==='client'?`<button class="btn primary" style="width:100%;margin-top:20px" data-act="request-new" data-id="${p.id}">Запросить предложение</button>`:''}</div></section><div class="notice">После выбора отправьте заявку. Подрядчик подготовит базовую смету. Проект создаётся только после того, как вы примете предложение.</div></aside></div>`;}
 function requests(){const s=state();return `${heading('Заявки и предложения',s.user.role==='client'?'Выберите исполнителя и согласуйте первоначальную смету.':'Получайте заявки и готовьте предложения заказчикам.',s.user.role==='client'?'<button class="btn primary" data-go="catalog">Найти исполнителя</button>':'')}<div class="request-list">${[...s.requests].reverse().map(r=>`<section class="panel"><div class="panel-head"><div><h2>${esc(r.title)}</h2><small>${esc(s.user.role==='client'?r.contractorName:r.clientName)} · ${esc(r.address)}</small></div><span class="badge ${r.status==='accepted'?'approved':r.status==='declined'?'rejected':'pending'}">${requestStatuses[r.status]}</span></div><div class="panel-body"><div class="chips"><span>${r.area} м²</span><span>${esc(r.repairClass)}</span><span>Бюджет заказчика ${money(r.targetBudget)}</span></div><p class="description">${esc(r.description)}</p>${r.quote?`<h3>Предложение подрядчика · ${money(r.quote.amount)}</h3>${c.linesTable(r.quote.lines)}<p class="muted">${esc(r.quote.comment)}</p>`:''}<div class="actions">${r.status==='requested'&&s.user.id===r.contractorId?`<button class="btn primary" data-act="quote-new" data-id="${r.id}">Подготовить первоначальную смету</button>`:''}${r.status==='quoted'&&s.user.id===r.clientId?`<button class="btn primary" data-act="request-accept" data-id="${r.id}">Принять и создать проект</button>`:''}${['requested','quoted'].includes(r.status)?`<button class="btn" data-act="request-decline" data-id="${r.id}">Отклонить заявку</button>`:''}${r.projectId?`<button class="btn primary" data-go="project" data-id="${r.projectId}">Открыть проект ${icon('arrow',15)}</button>`:''}<button class="link-btn" data-go="profile" data-id="${r.profileId}">Профиль исполнителя</button></div>${!c.serverMode()&&s.user.role==='client'?`<button class="btn small" data-act="demo-provider" data-id="${r.contractorId}">Демо: открыть кабинет этого исполнителя</button>`:''}<details class="request-history"><summary>История заявки</summary>${r.events.map(e=>`<p><strong>${esc(e.actor)}</strong> · ${esc(requestStatuses[e.status])}<br>${esc(e.comment)}</p>`).join('')}</details></div></section>`).join('')||empty('Заявок пока нет. Выберите исполнителя в каталоге.')}</div>`;}
 function myprofile(){const p=state().profiles.find(p=>p.ownerId===state().user.id);return p?profile(p.id):`${heading('Профиль исполнителя','Расскажите о своём опыте, расценках и специализации.','<button class="btn primary" data-act="profile-edit">Создать профиль</button>')}<div class="notice">После заполнения профиль появится в каталоге. Новые отзывы смогут оставить заказчики завершённых проектов.</div>`;}
 function profileEdit(){const p=state().profiles.find(p=>p.ownerId===state().user.id);openModal('Профиль исполнителя',`<form id="profile-form"><label class="field">Название бригады или имя<input name="name" required maxlength="200" value="${esc(p?.name||state().user.name)}"></label><div class="form-grid"><label class="field">Тип<select name="type">${['Бригада','Специалист'].map(v=>`<option ${p?.type===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Город<input name="city" required maxlength="80" value="${esc(p?.city||'Алматы')}"></label></div><label class="field">Специализация<input name="specialty" required maxlength="100" value="${esc(p?.specialty||'Ремонт под ключ')}"></label><div class="form-grid"><label class="field">Опыт, лет<input name="experience" type="number" min="0" max="60" step="1" value="${p?.experience||0}" required></label><label class="field">Ориентир цены, ₸ / м²<input name="rate" type="number" min="1" required value="${p?.rate||''}"></label><label class="field">От, м²<input name="minArea" type="number" min="1" required value="${p?.minArea||1}"></label><label class="field">До, м²<input name="maxArea" type="number" min="1" required value="${p?.maxArea||200}"></label></div><div class="field">Классы ремонта<div class="check-row">${repairClasses.map(v=>`<label><input type="checkbox" name="repairClasses" value="${v}" ${p?.repairClasses.includes(v)?'checked':''}> ${v}</label>`).join('')}</div></div><label class="field">О себе<textarea name="bio" maxlength="2000" required>${esc(p?.bio||'')}</textarea></label><label class="field">Публикация<select name="active"><option value="true">Показывать в каталоге</option><option value="false" ${p?.active===false?'selected':''}>Скрыть из каталога</option></select></label><div class="form-error" role="alert"></div><button class="btn primary">Сохранить профиль</button></form>`);}
 function requestNew(pid){const p=state().profiles.find(p=>p.id===pid);if(!p)return;openModal('Заявка · '+esc(p.name),`<form id="request-form" data-id="${p.id}"><div class="notice">Запрос не создаёт проект и не подтверждает итоговую цену. Сначала получите и проверьте предложение подрядчика.</div><label class="field">Название проекта<input name="title" required maxlength="200" placeholder="Ремонт квартиры в ЖК Nova"></label><label class="field">Адрес объекта<input name="address" required maxlength="200" placeholder="Город, улица, дом"></label><div class="form-grid"><label class="field">Площадь, м²<input name="area" type="number" min="${p.minArea}" max="${p.maxArea}" step="0.01" required placeholder="${p.minArea}–${p.maxArea}"></label><label class="field">Класс ремонта<select name="repairClass">${p.repairClasses.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label></div><label class="field">Планируемый бюджет, ₸<input name="targetBudget" type="number" min="1" required placeholder="2400000"></label><label class="field">Что требуется сделать<textarea name="description" required maxlength="3000" placeholder="Тип помещения, объём работ, пожелания к отделке и срокам"></textarea></label><div class="form-error" role="alert"></div><button class="btn primary">Отправить заявку</button></form>`);}
 function quoteNew(rid){openModal('Первоначальная смета',`<form id="quote-form" data-id="${rid}"><p class="muted">Укажите состав и стоимость работ. После принятия заказчиком эта смета станет базовым бюджетом проекта.</p><div class="baseline-row muted"><span>Работа</span><span>Ед.</span><span>Объём</span><span>Цена, ₸</span><span></span></div><div id="baseline-lines"></div><button class="link-btn" type="button" data-act="baseline-add">+ Добавить работу</button><div class="estimate-total" id="baseline-total"></div><label class="field">Комментарий и условия<textarea name="comment" required maxlength="2000" placeholder="Что включено, какие материалы и этапы учтены"></textarea></label><div class="form-error" role="alert"></div><button class="btn primary">Отправить предложение</button></form>`);c.addBaseline();}
 function projectActions(p){if(state().user.role!=='client')return '';const reviewed=state().reviews.some(r=>r.projectId===p.id);return `<div class="notice no-print">${p.completedAt?`Проект отмечен завершённым. ${reviewed?'Ваш отзыв опубликован.':`<button class="link-btn" data-act="review-new" data-id="${p.id}">Оставить отзыв об исполнителе</button>`}`:`<span>После окончания ремонта и согласования всех смет:</span> <button class="link-btn" data-act="project-finish" data-id="${p.id}">Завершить проект</button>`}</div>`;}
 async function click(act,b){const s=state();switch(act){
 case 'demo-provider':c.simulate(b.dataset.id);return true;
 case 'market-reset':filters={};c.render();return true;
 case 'profile-edit':profileEdit();return true;
 case 'portfolio-new':openModal('Работа в портфолио',`<form id="portfolio-form"><label class="field">Название<input name="title" required maxlength="200"></label><label class="field">Описание<textarea name="description" required maxlength="1000"></textarea></label><label class="field">Фото работы (необязательно)<input name="photo" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG, WebP до 400 КБ.</small></label><label class="field">Иллюстрация<select name="palette"><option value="sage">Зелёный интерьер</option><option value="sand">Тёплый интерьер</option><option value="clay">Терракота</option><option value="blue">Синий интерьер</option></select><small>Если фото не выбрано, используем иллюстрацию.</small></label><div class="form-error" role="alert"></div><button class="btn primary">Добавить работу</button></form>`);return true;
 case 'request-new':requestNew(b.dataset.id);return true;
 case 'quote-new':quoteNew(b.dataset.id);return true;
 case 'request-accept':{const r=s.requests.find(r=>r.id===b.dataset.id);openModal('Создать проект с этим исполнителем?',`<p>${esc(r.contractorName)} · ${esc(r.title)}</p><div class="budget-row total"><span>Первоначальная смета</span><strong>${money(r.quote.amount)}</strong></div><p>Принятая смета станет базовым бюджетом. Дополнительные работы будут согласовываться отдельно.</p><button class="btn primary" data-act="request-confirm" data-id="${r.id}" data-revision="${r.revision}">Принять и создать проект</button>`);return true;}
 case 'request-confirm':{const r=await c.action('request.accept',{id:b.dataset.id,revision:Number(b.dataset.revision)});await c.refresh();c.closeModal();c.go('project',{id:r.projectId});toast('Исполнитель выбран, проект и базовая смета созданы');return true;}
 case 'request-decline':{const r=s.requests.find(r=>r.id===b.dataset.id);openModal('Отклонить заявку',`<form id="decline-form" data-id="${r.id}" data-revision="${r.revision}"><label class="field">Причина<textarea name="comment" required maxlength="1000"></textarea></label><div class="form-error" role="alert"></div><button class="btn danger">Отклонить</button></form>`);return true;}
 case 'project-finish':openModal('Завершить проект?',`<p>Подтвердите, что ремонт закончен. После завершения можно оставить один отзыв об исполнителе. Новые дополнительные сметы станут недоступны.</p><button class="btn primary" data-act="project-finish-confirm" data-id="${b.dataset.id}">Подтвердить завершение</button>`);return true;
 case 'project-finish-confirm':await c.action('project.complete',{id:b.dataset.id});await c.refresh();c.closeModal();c.render();toast('Проект завершён. Теперь доступен отзыв.');return true;
 case 'review-new':openModal('Отзыв об исполнителе',`<form id="review-form" data-id="${b.dataset.id}"><label class="field">Оценка<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} ${'★'.repeat(n)}</option>`).join('')}</select></label><label class="field">Ваш опыт<textarea name="text" maxlength="2000" required></textarea></label><div class="form-error" role="alert"></div><button class="btn primary">Опубликовать отзыв</button></form>`);return true;
 }return false;}
 document.addEventListener('submit',async event=>{const form=event.target;if(!['market-filter-form','profile-form','portfolio-form','request-form','quote-form','decline-form','review-form'].includes(form.id))return;event.preventDefault();const button=form.querySelector('button.primary,button.danger');if(button?.disabled)return;if(button)button.disabled=true;try{
  const fd=new FormData(form),d=Object.fromEntries(fd);
  if(form.id==='market-filter-form'){filters=d;c.render();return;}
  if(form.id==='profile-form')await c.action('profile.save',{...d,repairClasses:fd.getAll('repairClasses'),experience:Number(d.experience),rate:Number(d.rate),minArea:Number(d.minArea),maxArea:Number(d.maxArea),active:d.active==='true'});
  if(form.id==='portfolio-form'){const file=fd.get('photo');let image='';if(file?.size){if(file.size>409600)throw Error('Фото должно быть не больше 400 КБ');image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Не удалось прочитать фото'));reader.readAsDataURL(file);});}await c.action('portfolio.add',{title:d.title,description:d.description,palette:d.palette,image});}
  if(form.id==='request-form')await c.action('request.create',{...d,profileId:form.dataset.id,area:Number(d.area),targetBudget:Number(d.targetBudget)});
  if(form.id==='quote-form'){const r=state().requests.find(r=>r.id===form.dataset.id);await c.action('request.quote',{id:r.id,revision:r.revision,lines:c.readBaseline(),comment:d.comment});}
  if(form.id==='decline-form')await c.action('request.decline',{id:form.dataset.id,revision:Number(form.dataset.revision),comment:d.comment});
  if(form.id==='review-form')await c.action('review.create',{projectId:form.dataset.id,rating:Number(d.rating),text:d.text});
  await c.refresh();c.closeModal();if(['request-form','quote-form','decline-form'].includes(form.id))c.go('requests');else if(['profile-form','portfolio-form'].includes(form.id))c.go('myprofile');else c.render();toast('Сохранено');
 }catch(e){const error=form.querySelector('.form-error');if(error)error.textContent=e.message;else toast(e.message,true);}finally{if(button?.isConnected)button.disabled=false;}});
 return {names,click,projectActions,content:route=>route.page==='catalog'?catalog():route.page==='profile'?profile(route.id):route.page==='requests'?requests():route.page==='myprofile'?myprofile():null};
}
